'use strict';
let access='',refreshToken='',rid='',snapshot=null,reviews=[],options={},sourceDocument={},plan=null,filterMode='all',queryText='',selected=new Set(),view='dashboard',tab='strategy',pollTimer=null,decisionBulk=false,lastProposal='';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),names={dashboard:'Dashboard',research:'Pesquisa científica',pre:'Prévia inicial',full:'Trabalho completo',editor:'Novo protocolo',detail:'Pesquisa científica'};
const stamp=t=>t?new Date(t*1000).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
function message(text,error=false){$('#message').hidden=!text;$('#message').textContent=text;$('#message').classList.toggle('error',error);}
async function api(path,opts={},retry=false){const headers={...(opts.raw?{}:{'Content-Type':'application/json'}),...opts.headers};if(access)headers.Authorization='Bearer '+access;const r=await fetch(path,{...opts,headers});if(r.status===401&&refreshToken&&!retry){const s=await fetch('/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:refreshToken})});if(s.ok){const d=await s.json();access=d.access_token;refreshToken=d.refresh_token;return api(path,opts,true);}}if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(typeof d.detail==='string'?d.detail:r.status===422?'Confira os campos, datas e critérios antes de continuar.':'Não foi possível concluir. Tente novamente.');}return r;}
async function action(fn,button){if(button){button.disabled=true;button.dataset.previous=button.textContent;button.textContent='Processando…';}try{await fn();}catch(e){message(e.message,true);}finally{if(button){button.disabled=false;button.textContent=button.dataset.previous;}}}
function show(name){message('');view=name;$$('.view').forEach(v=>v.hidden=v.id!==name+'View');$('#pageName').textContent=names[name]||name;$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name||['editor','detail'].includes(name)&&b.dataset.nav==='research'));if(name!=='detail'&&name!=='editor'&&name!=='pre')stopPolling();if(name==='pre')action(openWriting);$('#aiToggle').hidden=!access;window.scrollTo({top:0,behavior:'instant'});}
function metric(label,value,sub,icon){return `<div class="metric"><span>${label}</span><strong>${value}</strong><small>${sub}</small><i class="metric-icon">${icon}</i></div>`;}
function reviewCard(r){return `<button class="review-card" data-review="${esc(r.id)}"><div class="review-card-top"><span class="folder-icon">▱</span><span class="pill ${r.approved_at?'include':''}">${r.approved_at?'Em pesquisa':'Protocolo em revisão'}</span></div><h3>${esc(r.title)}</h3><div class="review-card-bottom"><span>PubMed · ${r.article_count??0} artigos</span><b>↗</b></div></button>`;}
function bindReviews(){ $$('[data-review]').forEach(b=>b.onclick=()=>action(()=>loadReview(b.dataset.review))); }
async function list(){reviews=await(await api('/reviews')).json();const html=reviews.length?reviews.map(reviewCard).join(''):'<div class="empty"><h3>Uma nova pergunta. Um novo caminho.</h3><p>Crie sua primeira pesquisa e reúna as evidências para o próximo trabalho.</p></div>';$('#reviews').innerHTML=html;$('#recentReviews').innerHTML=reviews.length?reviews.slice(0,3).map(reviewCard).join(''):html;const approved=reviews.filter(r=>r.approved_at).length;$('#dashboardMetrics').innerHTML=metric('Pesquisas no workspace',reviews.length,'Protocolos cadastrados','▱')+metric('Protocolos aprovados',approved,'Liberados para busca','✓')+metric('Artigos na biblioteca',reviews.reduce((n,r)=>n+(r.article_count||0),0),'Referências únicas por pesquisa','▤')+metric('Aguardando aprovação',reviews.length-approved,'Protocolos em revisão','◷');bindReviews();}
async function signed(){ $('#login').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;$('#newTop').hidden=false;const me=await(await api('/auth/me')).json();$('#userEmail').textContent=me.email;$('#aiToggle').hidden=false;await list();show('dashboard');message('');const linked=new URLSearchParams(location.search).get('review');if(linked)await loadReview(linked);}
$$('[data-nav]').forEach(b=>b.onclick=()=>{if(!access){message('Entre na sua conta para acessar o workspace.');return;}show(b.dataset.nav);if(b.dataset.nav==='dashboard'||b.dataset.nav==='research')action(list);});
$('#loginForm').onsubmit=e=>{e.preventDefault();action(async()=>{const d=await(await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))})).json();access=d.access_token;refreshToken=d.refresh_token;$('#loginForm').reset();await signed();},e.submitter);};
$('#demo').onclick=()=>action(async()=>{access='local-demo';await signed();});$('#logout').onclick=()=>{access='';refreshToken='';stopPolling();location.reload();};
const ageLabels={newborn:'Recém-nascido',infant:'Lactente',child:'Criança',adolescent:'Adolescente',adult:'Adulto',middle_aged:'Meia-idade',aged:'Idoso 65+',aged80:'Idoso 80+'};
function checks(field,values){return `<div class="check-grid">${Object.entries(values).map(([k,v])=>`<label><input type="checkbox" data-field="${field}" value="${esc(k)}">${esc(v)}</label>`).join('')}</div>`;}
function renderFilters(){ $('#filters').innerHTML=`<div class="filter-section"><strong>Tipos de estudo</strong>${checks('study_types',options.study_types||{})}</div><div class="filter-section"><strong>Idiomas</strong>${checks('languages',options.languages||{})}</div><div class="two-col"><label>Publicação a partir de<input type="date" data-field="date_from"></label><label>Publicação até<input type="date" data-field="date_to"></label></div><div class="two-col"><label>Espécie<select data-field="species"><option value="all">Sem restrição</option><option value="humans">Humanos</option><option value="animals">Animais</option></select></label><label>Sexo<select data-field="sex"><option value="all">Sem restrição</option><option value="female">Feminino</option><option value="male">Masculino</option></select></label></div><strong>Faixas etárias</strong>${checks('ages',ageLabels)}<div class="two-col"><label>Disponibilidade de texto<select data-field="availability"><option value="all">Sem restrição de acesso</option><option value="abstract">Com resumo</option><option value="full">Com texto completo</option><option value="free">Texto completo gratuito</option></select></label><label>Ordenar resultados<select data-field="sort"><option value="pub date">Mais recentes</option><option value="relevance">Melhor correspondência</option></select></label></div>${checks('flags',{medline:'Somente MEDLINE',exclude_preprints:'Excluir preprints'})}<label>Filtro avançado adicional<textarea data-field="advanced" maxlength="2000" placeholder='Ex.: nursing journals[sb] ou um filtro metodológico validado'></textarea><small>Permite campos e filtros adicionais da sintaxe PubMed.</small></label>`;}
function readFilters(){const out={study_types:[],languages:[],ages:[]};$$('#filters [data-field]').forEach(e=>{const k=e.dataset.field;if(e.type==='checkbox'){if(k==='flags')out[e.value]=e.checked;else if(e.checked)out[k].push(e.value);}else out[k]=e.value||(['date_from','date_to'].includes(k)?null:'');});return out;}
function fillFilters(f={}){$$('#filters [data-field]').forEach(e=>{const k=e.dataset.field;if(e.type==='checkbox')e.checked=k==='flags'?!!f[e.value]:(f[k]||[]).includes(e.value);else e.value=f[k]??(['species','sex','availability'].includes(k)?'all':k==='sort'?'pub date':'');});}
function formBody(assisting=false){const f=Object.fromEntries(new FormData($('#createForm'))),split=s=>String(s||'').split('\n').map(s=>s.trim()).filter(Boolean);return {title:f.title,protocol:{question:f.question||(assisting?'Pergunta em elaboração para o tema: '+f.title:''),inclusion:split(f.inclusion).length?split(f.inclusion):assisting?['Rascunho: definir critérios de inclusão antes da aprovação.']:[],exclusion:split(f.exclusion).length?split(f.exclusion):assisting?['Rascunho: definir critérios de exclusão antes da aprovação.']:[],observations:f.observations,max_records:Number(f.max_records),filters:readFilters(),source_document:sourceDocument,pico:plan?.pico||{},database:'pubmed',auto_search:f.auto_search==='on',clickup_task_id:snapshot?.review?.protocol?.clickup_task_id||''}};}
async function saveDraft(assisting=false){if(assisting&&!$('#createForm [name=title]').value.trim()&&sourceDocument.text)$('#createForm [name=title]').value='Pesquisa a partir da ficha: '+(sourceDocument.filename||'produção').replace(/\.[^.]+$/,'');const b=formBody(assisting);if(b.title.length<3)throw Error('Informe um título com pelo menos três caracteres.');if(!assisting&&!$('#createForm').reportValidity())throw Error('Preencha a pergunta e os critérios.');if(rid)await api(`/reviews/${rid}/draft`,{method:'PUT',body:JSON.stringify(b)});else{const r=await(await api('/reviews',{method:'POST',body:JSON.stringify(b)})).json();rid=r.id;}await list();return rid;}
function newResearch(){rid='';snapshot=null;sourceDocument={};plan=null;lastProposal='';selected.clear();$('#createForm').reset();fillFilters();$('#documentPreview').hidden=true;$('#uploadStatus').textContent='Selecionar documento';$('#planningStatus').innerHTML='';$('#themeSuggestions').innerHTML='';$('#editorTitle').innerHTML='Novo protocolo';show('editor');}
for(const id of ['newTop','newHero','newLibrary'])$('#'+id).onclick=newResearch;
for(const id of ['backLibrary','backDetail','allResearch','openResearch'])$('#'+id).onclick=()=>{show('research');action(list);};
$('#productionFile').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('A ficha deve ter até 10 MB.');$('#uploadStatus').textContent='Lendo documento…';sourceDocument=await(await api('/documents/extract',{method:'POST',raw:true,headers:{'X-Filename':encodeURIComponent(f.name),'Content-Type':'application/octet-stream'},body:f})).json();$('#documentText').textContent=sourceDocument.text;$('#documentPreview').hidden=false;$('#uploadStatus').textContent=f.name+' · texto extraído'+(sourceDocument.truncated?' · prévia limitada a 20.000 caracteres':'');});
$('#createForm').onsubmit=e=>{e.preventDefault();action(async()=>{await saveDraft();message('Rascunho salvo. Você pode continuar revisando antes de aprovar.');},e.submitter);};
$('#saveApprove').onclick=e=>action(async()=>{await saveDraft();if(formBody().protocol.inclusion.concat(formBody().protocol.exclusion).some(t=>t.startsWith('Rascunho:')))throw Error('Substitua os critérios provisórios antes de aprovar.');await api(`/reviews/${rid}/approve`,{method:'POST'});await loadReview(rid);message('Protocolo aprovado. Agora revise a estratégia e inicie a busca.');},e.currentTarget);
$('#suggestProtocol').onclick=e=>action(async()=>{await saveDraft(true);await api(`/reviews/${rid}/plan`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});message('Assistente na fila. Você pode sair: o planejamento continua na nuvem.');await pollReview();startPolling();},e.currentTarget);
function editDraft(s){const p=s.review.protocol;plan=latestPlan(s)?.payload.result||{pico:p.pico||{}};$('#createForm').reset();for(const key of ['title','question','observations','max_records']){const el=$(`#createForm [name="${key}"]`);el.value=key==='title'?s.review.title:p[key]??(key==='max_records'?50:'');}for(const key of ['inclusion','exclusion'])$(`#createForm [name="${key}"]`).value=(p[key]||[]).join('\n');$('#createForm [name=auto_search]').checked=!!p.auto_search;sourceDocument=p.source_document||{};fillFilters(p.filters);$('#documentPreview').hidden=!sourceDocument.text;$('#documentText').textContent=sourceDocument.text||'';$('#uploadStatus').textContent=sourceDocument.filename||'Selecionar documento';$('#editorTitle').textContent=s.review.title;$('#planningStatus').innerHTML='';$('#themeSuggestions').innerHTML='';show('editor');renderPlanning(s);renderEditorJobs(s);if(hasActive(s))startPolling();}
async function loadReview(id){stopPolling();if(id!==rid){$('#searchForm [name=query]').value='';lastProposal='';}rid=id;selected.clear();snapshot=await(await api('/reviews/'+id)).json();if(!snapshot.review.approved_at){editDraft(snapshot);return;}show('detail');renderDetail();if(hasActive(snapshot))startPolling();}
function hasActive(s){return s.jobs.some(j=>['pending','running','delivery_pending','delivery_running','cancel_requested','cancelling'].includes(j.status));}
function stopPolling(){if(pollTimer)clearInterval(pollTimer);pollTimer=null;}
function startPolling(){stopPolling();pollTimer=setInterval(()=>action(pollReview),5000);}
async function pollReview(){if(!rid||!access)return;const current=rid;const s=await(await api('/reviews/'+rid)).json();if(current!==rid)return;snapshot=s;if(view==='editor'){renderEditorJobs(s);renderPlanning(s);}if(view==='detail')renderDetail();if(view==='pre'){renderWritingActivity();checkWritingResponse();}if(!hasActive(s))stopPolling();}
const jobLabels={pubmed:'Busca PubMed',browser:'Recomendação de artigos',planning:'Protocolo e estratégias',writing:'Assistência à prévia',pdf:'Recuperação de PDF',drive:'Entrega no Drive',clickup:'Atualização no ClickUp'};
function jobStatus(j){
 const states={pending:'Aguardando próxima etapa',running:'Em processamento',done:'Concluída',done_with_warnings:'Concluída · revisar alertas',failed:'Falha',needs_reconciliation:'Conferência necessária',cancel_requested:'Cancelamento solicitado',cancelling:'Cancelando no provedor',cancelled:'Cancelada',cancel_unknown:'Cancelada localmente · conferir provedor',delivery_pending:'Entrega na fila',delivery_running:'Entregando'};
 const p=j.payload||{},progress=p.progress||{},active=['pending','running','cancel_requested','cancelling','delivery_pending','delivery_running'].includes(j.status),failed=['failed','needs_reconciliation','cancel_unknown'].includes(j.status),v=p.validation;
 let desc=p.provider_status?`Provedor: ${p.provider_status} · conferido em ${stamp(p.provider_checked_at)}`:j.external_id?'Execução enviada; aguarda confirmação do estado remoto.':'Nenhuma execução remota iniciada.';
 if(j.kind==='pubmed'&&progress.found!==undefined)desc=`${progress.found} localizados · ${progress.fetched||0} / ${progress.target||0} recebidos`;
 if(v)desc=`${v.verified} evidências validadas · ${v.manual_review} artigos para revisão`;
 const cancellable=['browser','planning','writing','pubmed','pdf'].includes(j.kind)&&['pending','running','failed','needs_reconciliation','cancel_unknown'].includes(j.status);
 return `<div class="job-card ${failed?'job-error':''}"><div class="job-state">${active?'<i class="spinner"></i>':`<span class="job-state-icon">${j.status==='done'?'✓':j.status==='done_with_warnings'?'!':'◷'}</span>`}<div><strong>${esc(jobLabels[j.kind]||j.kind)}</strong><span class="pill">${esc(states[j.status]||j.status)}</span><p>${esc(desc)}</p><small>Solicitada ${stamp(j.created_at)}${p.last_activity_at?' · atividade '+stamp(p.last_activity_at):''}${j.error?' · '+esc(j.error):''}</small></div></div><div class="job-buttons"><button class="button ghost small" data-job-log="${j.id}">Ver atividade</button>${cancellable?`<button class="button ghost small" data-job-cancel="${j.id}">Cancelar</button>`:''}${j.status==='failed'?`<button class="button secondary small" data-retry="${j.id}">${j.external_id?'Reprocessar resposta existente':'Tentar novamente'}</button>`:''}</div>${j.status==='needs_reconciliation'&&['browser','planning','writing'].includes(j.kind)?`<details><summary>Vincular execução existente</summary><label>ID da execução no Browser Use<input data-run="${j.id}"></label><button class="button secondary small" data-reconcile="${j.id}">Vincular sem nova execução</button></details>`:''}</div>`;
}
let activeLogId='',cancelJobId='';
function bindJobs(){
 $$('[data-retry]').forEach(b=>b.onclick=()=>action(async()=>{await api(`/reviews/${rid}/jobs/${b.dataset.retry}/retry`,{method:'POST'});await pollReview();startPolling();},b));
 $$('[data-reconcile]').forEach(b=>b.onclick=()=>action(async()=>{const run_id=$(`[data-run="${b.dataset.reconcile}"]`).value;await api(`/reviews/${rid}/jobs/${b.dataset.reconcile}/reconcile`,{method:'POST',body:JSON.stringify({run_id})});await pollReview();startPolling();},b));
 $$('[data-job-log]').forEach(b=>b.onclick=()=>action(async()=>{activeLogId=b.dataset.jobLog;$('#jobLogDialog').showModal();await loadJobLog(false);}));
 $$('[data-job-cancel]').forEach(b=>b.onclick=()=>{cancelJobId=b.dataset.jobCancel;$('#jobCancelDialog').showModal();});
}
async function loadJobLog(remote=false){$('#jobLogContent').textContent='Consultando atividade…';const d=await(await api(`/reviews/${rid}/jobs/${activeLogId}/logs`+(remote?'?refresh_provider=true':''))).json();$('#verifyJob').disabled=!d.run_id;const r=d.remote||{};$('#jobLogContent').innerHTML=`<dl class="job-facts"><dt>Estado no sistema</dt><dd>${esc(d.status)}</dd><dt>Execução no provedor</dt><dd>${esc(d.run_id||'Não iniciada')}</dd><dt>Estado confirmado no provedor</dt><dd>${esc(r.status||d.provider_status||'Ainda não consultado')}</dd><dt>Última verificação</dt><dd>${stamp(d.remote_checked_at||d.provider_checked_at)}</dd><dt>Última atividade local</dt><dd>${stamp(d.last_activity_at)}</dd><dt>Próxima etapa prevista</dt><dd>${stamp(d.next_check_at)}</dd></dl>${d.remote_error?`<p class="cautions">${esc(d.remote_error)}</p>`:''}${d.validation.expected?`<p class="cautions">${d.validation.verified} / ${d.validation.expected} evidências validadas. ${d.validation.manual_review} precisam de revisão.</p>`:''}<div class="timeline">${d.events.map(e=>`<div class="timeline-item"><small>${stamp(e.at)}</small><strong>${esc(e.message)}</strong><pre>${esc(JSON.stringify(e.details,null,2))}</pre></div>`).join('')||'<p class="muted">Esta execução antecede o histórico detalhado. O estado e o ID acima são os dados reais disponíveis.</p>'}</div>`;}
$('#closeJobLog').onclick=()=>$('#jobLogDialog').close();$('#closeJobCancel').onclick=()=>$('#jobCancelDialog').close();$('#verifyJob').onclick=e=>action(()=>loadJobLog(true),e.currentTarget);$('#downloadJobLog').onclick=()=>action(()=>download(`/reviews/${rid}/jobs/${activeLogId}/logs`,'atividade-'+activeLogId+'.json'));
$('#confirmJobCancel').onclick=e=>action(async()=>{const d=await(await api(`/reviews/${rid}/jobs/${cancelJobId}/cancel`,{method:'POST'})).json();$('#jobCancelDialog').close();message(d.message||'Cancelamento registrado.');await pollReview();startPolling();},e.currentTarget);
function renderEditorJobs(s){const j=s.jobs.filter(j=>j.kind==='planning').sort((a,b)=>b.created_at-a.created_at)[0];$('#planningStatus').innerHTML=j?`<div class="compact-activity">${['pending','running'].includes(j.status)?'<i class="spinner"></i>':''}<span>Planejamento · ${esc(j.status)}</span><button data-job-log="${j.id}">Ver atividade</button></div>`:'';bindJobs();}
function latestPlan(s){return [...s.jobs].filter(j=>j.kind==='planning'&&j.status==='done'&&j.payload.result).sort((a,b)=>b.created_at-a.created_at)[0];}
function planHTML(j){if(!j)return '<p class="muted">Solicite sugestões ou construa sua própria string. O protocolo aprovado permanece inalterado.</p>';const p=j.payload.result,checked=j.payload.mesh_verification||[];return `<div class="concepts">${checked.map(m=>`<span class="concept">${esc(m.term)} <small>${m.verified?'✓ MeSH verificado':'não confirmado'}</small></span>`).join('')}</div>${p.concepts.map(c=>`<p class="fine"><strong>${esc(c.label)}</strong> · ${c.synonyms.map(esc).join(' · ')}</p>`).join('')}${p.cautions?.length?`<div class="cautions">${p.cautions.map(esc).join('<br>')}</div>`:''}${p.strategies.map((s,i)=>`<div class="strategy-card"><h3>${esc(s.label)}</h3><p>${esc(s.rationale)}</p><pre>${esc(s.query)}</pre><button class="button secondary small" data-use-strategy="${i}">Usar esta estratégia →</button></div>`).join('')}`;}
function renderPlanning(s){const j=latestPlan(s);if(view==='editor'&&j&&lastProposal!==j.id){lastProposal=j.id;plan=j.payload.result;$('#themeSuggestions').innerHTML=`<div class="strategy-card"><span class="eyebrow">PROPOSTA DO ASSISTENTE · REVISE ANTES DE APROVAR</span>${plan.themes.map(t=>`<button type="button" class="button ghost small theme-button" data-theme="${esc(t)}">${esc(t)}</button>`).join('')}<p>${esc(plan.question)}</p><button type="button" class="button secondary" id="applyProposal">Aplicar critérios e filtros sugeridos ↓</button>${plan.cautions?.length?`<p class="cautions">${plan.cautions.map(esc).join('<br>')}</p>`:''}</div>`;$$('[data-theme]').forEach(b=>b.onclick=()=>{$('#createForm [name=title]').value=b.dataset.theme;});$('#applyProposal').onclick=()=>{for(const key of ['question','inclusion','exclusion'])$(`#createForm [name=${key}]`).value=Array.isArray(plan[key])?plan[key].join('\n'):plan[key];fillFilters(plan.filters);message('Sugestões aplicadas ao formulário. Revise e salve ou aprove o protocolo.');};}}
function finalQuery(q,f){const types={randomized:'Randomized Controlled Trial[pt]',clinical:'Clinical Trial[pt]',meta:'Meta-Analysis[pt]',systematic:'systematic[sb]',review:'Review[pt]',observational:'Observational Study[pt]',cohort:'Cohort Studies[mh]',case_control:'Case-Control Studies[mh]',cross_sectional:'Cross-Sectional Studies[mh]',qualitative:'Qualitative Research[mh]',case_report:'Case Reports[pt]',guideline:'Guideline[pt]',comparative:'Comparative Study[pt]',validation:'Validation Study[pt]'},ages={child:'child[mh]',adolescent:'adolescent[mh]',adult:'adult[mh]',middle_aged:'middle aged[mh]',aged:'aged[mh]',aged80:'aged, 80 and over[mh]',infant:'infant[mh]',newborn:'infant, newborn[mh]'},c=[];for(const v of [(f.study_types||[]).map(x=>types[x]),(f.languages||[]).map(x=>x+'[la]'),(f.ages||[]).map(x=>ages[x])])if(v.length)c.push('('+v.join(' OR ')+')');if(f.date_from||f.date_to)c.push(`("${(f.date_from||'1000-01-01').replaceAll('-','/')}"[dp] : "${(f.date_to||'3000-12-31').replaceAll('-','/')}"[dp])`);if(f.species&&f.species!=='all')c.push(f.species+'[mh]');if(f.sex&&f.sex!=='all')c.push(f.sex+'[mh]');if(f.availability&&f.availability!=='all')c.push({abstract:'hasabstract',full:'full text[sb]',free:'free full text[sb]'}[f.availability]);if(f.medline)c.push('medline[sb]');if(f.exclude_preprints)c.push('NOT preprint[pt]');if(f.advanced?.trim())c.push('('+f.advanced.trim()+')');return c.length?'('+q.trim()+')'+c.map(x=>(x.startsWith('NOT ')?' ':' AND ')+x).join(''):q.trim();}
function previewQuery(){if(snapshot){const q=$('#searchForm [name=query]').value;$('#queryPreview').textContent=q.trim()?finalQuery(q,snapshot.review.protocol.filters||{}):'Preencha a string base para conferir a combinação com os filtros.';}}
$('#searchForm [name=query]').oninput=previewQuery;
function setTab(t){tab=t;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$$('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==t);if(t==='delivery')action(renderPrisma);}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
function renderDetail(){const s=snapshot,p=s.prisma;$('#reviewTitle').textContent=s.review.title;$('#approvalStatus').textContent='Protocolo aprovado · PubMed · '+stamp(s.review.approved_at);$('#protocol').textContent=JSON.stringify(s.review.protocol,null,2);$('#articleCount').textContent=s.articles.length;$('#metrics').innerHTML=metric('Registros importados',p.identified,'De todas as estratégias','⌕')+metric('Duplicatas removidas',p.duplicates_removed,'Por DOI / PMID','⇄')+metric('Referências únicas',s.articles.length,p.title_abstract_pending+' aguardam triagem','▤')+metric('Artigos aceitos',p.reports_sought,p.included_reports+' incluídos após texto completo','✓');$('#jobs').innerHTML='<details class="job-panel" open><summary>Atividade e controle das análises</summary>'+s.jobs.slice().sort((a,b)=>b.created_at-a.created_at).map(jobStatus).join('')+'</details>';renderCompactActivities();renderNextSteps();bindJobs();const j=latestPlan(s);$('#planningResults').innerHTML=planHTML(j);$$('[data-use-strategy]').forEach(b=>b.onclick=()=>{$('#searchForm [name=query]').value=j.payload.result.strategies[Number(b.dataset.useStrategy)].query;previewQuery();$('#searchForm').scrollIntoView({behavior:'smooth',block:'center'});});if(!$('#searchForm [name=query]').value&&j){$('#searchForm [name=query]').value=j.payload.result.strategies[0].query;}if(!$('#searchForm [name=max_records]').dataset.edited)$('#searchForm [name=max_records]').value=s.review.protocol.max_records||50;previewQuery();$('#searchHistory').innerHTML=s.searches.length?s.searches.sort((a,b)=>a.created_at-b.created_at).map((a,i)=>{const stats=a.raw.stats||{},raw=a.raw;return `<div class="search-row"><div class="search-row-header"><strong>ESTRATÉGIA #${i+1}</strong><span>${stamp(raw.executed_at||a.created_at)}</span></div><pre>${esc(a.query)}</pre><div class="stats"><span>${a.total_found} localizados na base</span><span>${stats.imported??s.records.filter(x=>x.search_id===a.id).length} importados</span><span>${stats.duplicates??'—'} duplicatas</span></div><details><summary>Search Details · string traduzida</summary><pre>${esc(a.translated_query||'Aguardando resposta do PubMed')}</pre></details></div>`;}).join(''):'<p class="muted">Nenhuma estratégia executada. A primeira busca começa acima.</p>';renderSelectionTarget();renderArticles();renderDelivery();$('#auditHistory').innerHTML=[...s.audit].sort((a,b)=>b.created_at-a.created_at).map(a=>`<div class="timeline-item"><small>${stamp(a.created_at)} · ${esc(a.actor)}</small><strong>${esc(a.action.replaceAll('_',' '))}</strong><details><summary>Detalhes do evento</summary><pre>${esc(JSON.stringify(a.payload,null,2))}</pre></details></div>`).join('');setTab(tab);}
$('#searchForm [name=max_records]').oninput=e=>e.target.dataset.edited='true';
function decisionsMap(){const m={};[...snapshot.decisions].sort((a,b)=>a.created_at-b.created_at||a.id.localeCompare(b.id)).forEach(d=>m[d.article_id+':'+d.stage]=d);return m;}
function articleOccurrences(a){return snapshot.records.filter(r=>r.article_id===a.id);}
const verdictLabels={include:'Incluir',exclude:'Excluir',uncertain:'Avaliar',not_retrieved:'Não obtido'};
function renderArticles(){const d=decisionsMap(),q=$('#articleSearch').value.toLowerCase(),s=snapshot;const filtered=s.articles.filter(a=>{const ta=d[a.id+':title_abstract'];return (filterMode==='all'||filterMode==='recommended'&&a.recommendation.recommendation==='include'||filterMode==='pending'&&(!ta||ta.verdict==='uncertain')||filterMode==='included'&&ta?.verdict==='include'||filterMode==='duplicates'&&articleOccurrences(a).length>1)&&(!q||(a.metadata_json.title+' '+a.metadata_json.abstract+' '+a.metadata_json.doi).toLowerCase().includes(q));}).sort((a,b)=>(b.recommendation.recommendation==='include')-(a.recommendation.recommendation==='include'));$('#selectionSummary').textContent=filtered.length+' referências · '+selected.size+' selecionadas';$('#articles').innerHTML=filtered.map(a=>{const m=a.metadata_json,rec=a.recommendation,ta=d[a.id+':title_abstract'],ft=d[a.id+':full_text'],occ=articleOccurrences(a),stage=ta?.verdict==='include'?'full_text':'title_abstract',canAccept=rec.recommendation==='include'&&!ft;return `<article class="article-card ${rec.recommendation==='include'?'recommended':''}"><div><input class="article-select" type="checkbox" data-select="${a.id}" aria-label="Selecionar recomendação para ${esc(m.title)}" ${selected.has(a.id)?'checked':''} ${canAccept?'':'disabled'}></div><div><div class="article-top"><div class="article-labels"><span class="pill">PubMed</span>${rec.recommendation?`<span class="pill ${esc(rec.recommendation)}">${rec.recommendation==='include'?'✧ Recomendado':rec.recommendation==='exclude'?'Não recomendado':'Revisar aderência'}</span>`:''}${occ.length>1?`<span class="pill duplicate">${occ.length-1} duplicata(s)</span>`:''}</div><span class="article-meta">PMID ${esc(m.pmid)} · ${esc(m.year||'s.d.')}</span></div><h3>${esc(m.title)}</h3><p class="article-authors">${esc((m.authors||[]).slice(0,3).join('; '))}${m.authors?.length>3?' et al.':''} · ${esc(m.journal)}</p><div class="article-links"><a href="https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(m.pmid)}/" target="_blank" rel="noopener noreferrer">Ver no PubMed ↗</a>${m.doi?`<a href="https://doi.org/${encodeURIComponent(m.doi)}" target="_blank" rel="noopener noreferrer">DOI / Editora ↗</a>`:''}${a.pdf.status==='available'?`<button data-pdf="${a.id}">Ver PDF ↗</button>`:''}</div><details><summary>Ler abstract</summary><p class="abstract-text">${esc(m.abstract||'Resumo não disponível na base.')}</p></details>${occ.length>1?`<details><summary>Ocorrências por estratégia</summary>${occ.map(o=>`<p class="fine">${esc(s.searches.find(x=>x.id===o.search_id)?.query||o.search_id)}</p>`).join('')}</details>`:''}${rec.reason?`<div class="recommendation"><strong>✧ ${rec.recommendation==='include'?'Minha recomendação: incluir na triagem':rec.recommendation==='exclude'?'Minha recomendação: excluir da triagem':'Minha recomendação: avaliar com atenção'}</strong><p>${esc(rec.reason)}</p>${rec.evidence_status==='manual_review_required'?'<p class="cautions">Evidência não validada. A proposta foi separada para revisão humana.</p>':''}${rec.quote?`<blockquote>“${esc(rec.quote)}”</blockquote>`:''}</div>`:'<p class="fine">Aguardando recomendação do assistente. Você também pode decidir manualmente.</p>'}${ta?`<p class="fine"><strong>Título/resumo: ${verdictLabels[ta.verdict]}</strong> · ${esc(ta.reason)}</p>`:''}${ft?`<p class="fine"><strong>Texto completo: ${verdictLabels[ft.verdict]}</strong> · ${esc(ft.reason)}</p>`:''}<div class="article-footer"><span class="muted">${ta?.verdict==='include'?'Avaliação de texto completo':'Decisão de título e resumo'} · PDF ${a.pdf.status==='available'?'disponível':a.pdf.status?'não disponível':'não solicitado'}</span><div class="decision-actions">${!ft?['exclude','uncertain','include',...(stage==='full_text'&&a.pdf.status!=='available'?['not_retrieved']:[])].map(v=>`<button data-decision="${a.id}" data-stage="${stage}" data-verdict="${v}" ${stage==='full_text'&&a.pdf.status!=='available'&&['include','exclude'].includes(v)?'disabled':''}>${verdictLabels[v]}</button>`).join(''):'<span class="pill include">Decisão registrada</span>'}</div></div>${a.pdf.status==='available'?`<details><summary>Registrar dados da matriz com página e citação</summary><form class="extract" data-article="${a.id}"><div class="two-col"><label>Campo<input name="field" required placeholder="Ex.: amostra"></label><label>Valor<input name="value" required></label></div><label>Página<input name="page" type="number" min="1" max="${a.pdf.pages||1000}" required></label><label>Citação literal<textarea name="quote" minlength="5" required></textarea></label><button class="button secondary small">Validar e salvar evidência</button></form></details>`:''}</div></article>`;}).join('')||'<div class="empty"><h3>Nenhum artigo nesta seleção.</h3><p>Execute uma estratégia ou ajuste os filtros de visualização.</p></div>';$$('[data-select]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select);$('#selectionSummary').textContent=filtered.length+' referências · '+selected.size+' selecionadas';});$$('[data-decision]').forEach(b=>b.onclick=()=>openDecision(b.dataset.decision,b.dataset.stage,b.dataset.verdict));$$('[data-pdf]').forEach(b=>b.onclick=()=>action(()=>download(`/reviews/${rid}/articles/${b.dataset.pdf}/pdf`,'artigo.pdf',true)));$$('.extract').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(async()=>{const item=Object.fromEntries(new FormData(f));item.page=Number(item.page);const a=s.articles.find(a=>a.id===f.dataset.article);await api(`/reviews/${rid}/articles/${a.id}/extraction`,{method:'POST',body:JSON.stringify({items:[...(a.extraction.items||[]),item]})});message('Citação conferida na página e dados salvos na matriz.');await pollReview();},e.submitter);});}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filterMode=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderArticles();});$('#articleSearch').oninput=()=>renderArticles();
function openDecision(aid,stage,verdict){decisionBulk=false;const a=snapshot.articles.find(a=>a.id===aid),f=$('#decisionForm');f.reset();f.elements.article_id.value=aid;f.elements.stage.value=stage;f.elements.verdict.value=verdict;$('#decisionTitle').textContent=verdictLabels[verdict]+' · '+(stage==='title_abstract'?'título/resumo':'texto completo');$('#decisionArticle').textContent=a.metadata_json.title;if(a.recommendation.recommendation===verdict)f.elements.reason.value='Concordo com a recomendação após revisar os critérios: '+a.recommendation.reason;$('#decisionDialog').showModal();}
$('#closeDecision').onclick=()=>$('#decisionDialog').close();$('#acceptSelected').onclick=()=>{if(!selected.size){message('Selecione os artigos recomendados que deseja aceitar.');return;}decisionBulk=true;$('#decisionForm').reset();$('#decisionTitle').textContent='Aceitar '+selected.size+' recomendação(ões)';$('#decisionArticle').textContent='Aprova a inclusão em título/resumo e agenda a busca dos PDFs legais. O texto completo precisará da sua avaliação.';$('#decisionForm [name=reason]').value='Revisei os critérios e concordo com a recomendação de inclusão em título/resumo para os artigos selecionados.';$('#decisionDialog').showModal();};
$('#decisionForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(e.target));if(decisionBulk){await api(`/reviews/${rid}/recommendations/accept`,{method:'POST',body:JSON.stringify({article_ids:[...selected],reason:f.reason})});selected.clear();}else await api(`/reviews/${rid}/articles/${f.article_id}/decisions`,{method:'POST',body:JSON.stringify({stage:f.stage,verdict:f.verdict,reason:f.reason})});$('#decisionDialog').close();await pollReview();startPolling();message('Seleção salva. Próximo passo: preparar o pacote e iniciar a Prévia inicial. Os PDFs são procurados automaticamente.');setTab('delivery');},e.submitter);};
$('#searchForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(e.target));await api(`/reviews/${rid}/searches`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({query:f.query,max_records:Number(f.max_records),automatic_screening:f.automatic_screening==='on'})});message('Estratégia na fila. O andamento abaixo será atualizado automaticamente.');await pollReview();startPolling();},e.submitter);};
$('#suggestStrategies').onclick=e=>action(async()=>{await api(`/reviews/${rid}/plan`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});await pollReview();startPolling();message('Verificando descritores e preparando propostas de strings.');},e.currentTarget);
$('#browser').onclick=e=>action(async()=>{await api(`/reviews/${rid}/browser`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});await pollReview();startPolling();message('Recomendações na fila. A seleção final continua com você.');},e.currentTarget);$('#refresh').onclick=()=>action(pollReview);
async function download(path,name,open=false){const r=await api(path),url=URL.createObjectURL(await r.blob());if(open){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();}else{const a=document.createElement('a');a.href=url;a.download=name;a.click();}setTimeout(()=>URL.revokeObjectURL(url),60000);}
$$('[data-export]').forEach(b=>b.onclick=()=>action(()=>download(`/reviews/${rid}/export/${b.dataset.export}`,'fullmark-'+rid+'.'+b.dataset.export),b));
let prismaUrl='';async function renderPrisma(){if(!snapshot||tab!=='delivery')return;const r=await api(`/reviews/${rid}/export/svg`);if(prismaUrl)URL.revokeObjectURL(prismaUrl);prismaUrl=URL.createObjectURL(await r.blob());$('#prismaPreview').innerHTML=`<img src="${prismaUrl}" alt="Fluxo PRISMA da pesquisa com as contagens e pendências atuais">`;}
function renderDelivery(){const d=decisionsMap(),included=snapshot.articles.filter(a=>d[a.id+':title_abstract']?.verdict==='include');$('#pdfAvailability').innerHTML=included.length?included.map(a=>`<div class="availability-row"><div><strong>${esc(a.metadata_json.title)}</strong><p>${a.pdf.status==='available'?'✓ PDF legal disponível · '+(a.pdf.pages||'')+' páginas':esc(a.pdf.reason||'Recuperação ainda não concluída')}</p>${a.pdf.status!=='available'?`<a href="https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(a.metadata_json.pmid)}/" target="_blank" rel="noopener noreferrer">Consultar acesso pela plataforma ↗</a>${a.metadata_json.doi?` · <a href="https://doi.org/${encodeURIComponent(a.metadata_json.doi)}" target="_blank" rel="noopener noreferrer">DOI / editora ↗</a>`:''}<label class="fine">Enviar PDF obtido com acesso autorizado<input type="file" accept=".pdf" data-upload-pdf="${a.id}"></label>`:''}</div><span class="pill ${a.pdf.status==='available'?'include':'uncertain'}">${a.pdf.status==='available'?'Disponível':'Pendente'}</span></div>`).join(''):'<p class="muted">Inclua artigos na triagem para iniciar a obtenção dos PDFs.</p>';if(!$('#clickupTask').value)$('#clickupTask').value=snapshot.review.protocol.clickup_task_id||'';const deliveries=snapshot.jobs.filter(j=>j.kind==='drive');const last=deliveries[deliveries.length-1];$('#driveStatus').innerHTML=last?.payload.folder_id?`<a href="https://drive.google.com/drive/folders/${encodeURIComponent(last.payload.folder_id)}" target="_blank" rel="noopener noreferrer">Abrir pasta da pesquisa ↗</a><br>${last.status==='done'?'Entrega concluída.':`${Object.keys(last.payload.completed||{}).length} / ${(last.payload.assets||[]).length} arquivos enviados · ${last.status==='needs_reconciliation'?'conferência necessária':'envio na nuvem'}`}`:last?'Criando a pasta da pesquisa no Drive…':'';}
$('#saveDrive').onclick=e=>action(async()=>{const r=await(await api(`/reviews/${rid}/deliver/drive`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})).json();message(r.message||'Entrega no Drive solicitada.');await pollReview();startPolling();},e.currentTarget);
$('#notifyClickup').onclick=e=>action(async()=>{const task_id=$('#clickupTask').value.trim();if(!task_id)throw Error('Informe o ID da tarefa ClickUp que deve receber a atualização.');await api(`/reviews/${rid}/deliver/clickup`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({task_id})});await pollReview();startPolling();message('Atualização da tarefa solicitada.');},e.currentTarget);
$('#passwordForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=Object.fromEntries(new FormData(e.target));if(f.password!==f.confirm)throw Error('As senhas precisam ser iguais.');await api('/auth/password',{method:'POST',body:JSON.stringify({password:f.password})});e.target.reset();$('#passwordSetup').hidden=true;await signed();},e.submitter);};
action(async()=>{options=await(await api('/research/options')).json();renderFilters();$('#today').textContent=new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')){access=fragment.get('access_token');refreshToken=fragment.get('refresh_token')||'';history.replaceState(null,'',location.pathname+location.search);const me=await(await api('/auth/me')).json();if(['invite','recovery'].includes(fragment.get('type'))){$('#login').hidden=true;$('#passwordSetup').hidden=false;$('#accountEmail').textContent='Conta: '+me.email;}else await signed();}const c=await(await api('/config')).json();$('#demo').hidden=!c.demo_mode;if(fragment.has('error_description')){history.replaceState(null,'',location.pathname+location.search);message(fragment.get('error_description'),true);}});

function renderSelectionTarget(){const s=snapshot.selection_summary||{};if(document.activeElement!==$('#targetCount'))$('#targetCount').value=s.target||'';$('#targetSummary').textContent=s.target?`${s.eligible} sugestões de inclusão com evidência para uma meta de ${s.target}. ${s.shortfall?`Faltam ${s.shortfall}; não completaremos a meta relaxando os critérios.`:'Você pode revisar e selecionar até a meta.'} ${s.manual_review||0} evidências precisam de conferência.`:'Defina a quantidade desejada. A IA não substituirá os critérios para preencher a meta.';}
$('#saveTarget').onclick=e=>action(async()=>{const target=Number($('#targetCount').value);if(!target||target<1||target>200)throw Error('Defina uma meta entre 1 e 200.');await api(`/reviews/${rid}/selection-target`,{method:'POST',body:JSON.stringify({target})});await pollReview();message('Meta registrada. Isso não aprova artigos automaticamente.');},e.currentTarget);
$('#chooseTarget').onclick=()=>{const s=snapshot.selection_summary;if(!s?.target){message('Defina e salve a meta de pré-seleção primeiro.');return;}const d=decisionsMap();selected=new Set(s.suggested_ids.filter(id=>!d[id+':full_text']&&d[id+':title_abstract']?.verdict!=='exclude'));renderArticles();message(`${selected.size} sugestões selecionadas para sua conferência. Use Aceitar selecionados para registrar sua decisão.`);};


function renderCompactActivities(){for(const pane of ['strategy','screening','delivery']){const kinds=pane==='strategy'?['planning','pubmed']:pane==='screening'?['browser']:['pdf','drive','clickup'];const active=snapshot.jobs.filter(j=>kinds.includes(j.kind)&&['pending','running','delivery_pending','delivery_running','cancel_requested','cancelling'].includes(j.status));const el=$(`[data-activity="${pane}"]`);el.innerHTML=active.length?`<i class="spinner"></i><span>${esc(jobLabels[active[0].kind])} · ${active.length} atividade(s) em curso</span><button data-history>Ver no Histórico →</button>`:'';}$$('[data-history]').forEach(b=>b.onclick=()=>setTab('history'));}
function renderNextSteps(){const p=snapshot.prisma,accepted=p.reports_sought||0,available=p.reports_available||0;$('#nextSteps').innerHTML=accepted?`<div><strong>Seleção aceita · ${accepted} artigo(s)</strong><p>${available} PDF(s) disponível(is) · ${p.reports_retrieval_pending} com acesso pendente · ${p.full_text_pending} aguardando avaliação do texto completo.</p><p>Baixe o pacote e comece a prévia. O PRISMA permanece parcial enquanto houver avaliações pendentes.</p></div><button class="button primary" id="prepareResearch">Preparar pacote e continuar →</button>`:`<div><strong>Próximo passo: revisar e aceitar os artigos</strong><p>Confira as recomendações em Artigos & seleção e aceite os artigos que deseja usar.</p></div><button class="button secondary" id="goSelection">Abrir seleção →</button>`;if($('#prepareResearch'))$('#prepareResearch').onclick=e=>action(async()=>{const d=await(await api(`/reviews/${rid}/prepare-delivery`,{method:'POST'})).json();await pollReview();startPolling();setTab('delivery');message(d.message);},e.currentTarget);if($('#goSelection'))$('#goSelection').onclick=()=>setTab('screening');}
let writingData=null,writingDirty=false,writingLoadedRid='',writingTimer=null,writingResponseId='',writingProposal=null,commentSelection='';
function draftBody(){return {revision:writingData?.revision||'',title:$('#draftTitle').value,theme:$('#draftTheme').value,client:$('#draftClient').value,instructions:$('#draftInstructions').value,production_text:$('#draftProduction').value,content:$('#draftContent').value};}
async function openWriting(){const select=$('#writingReview');select.innerHTML='<option value="">Selecione uma pesquisa</option>'+reviews.filter(r=>r.approved_at).map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('');if(rid&&reviews.some(r=>r.id===rid&&r.approved_at))select.value=rid;$('#writingWorkspace').hidden=!select.value;if(!select.value){$('#aiToggle').hidden=true;return;}if(writingLoadedRid===rid){renderWritingActivity();return;}await loadWriting(select.value);}
async function loadWriting(id){if(writingDirty)await saveWriting();stopPolling();rid=id;snapshot=await(await api('/reviews/'+rid)).json();writingData=await(await api(`/reviews/${rid}/writing`)).json();writingLoadedRid=rid;writingDirty=false;writingResponseId='';writingProposal=null;$('#applyAi').hidden=true;$('#aiReply').textContent='';const d=writingData.draft;for(const [id,key] of [['draftTitle','title'],['draftTheme','theme'],['draftClient','client'],['draftInstructions','instructions'],['draftProduction','production_text'],['draftContent','content']])$('#'+id).value=d[key]||'';$('#writingWorkspace').hidden=false;$('#aiToggle').hidden=false;renderWritingMeta();renderWritingActivity();checkWritingResponse();if(hasActive(snapshot))startPolling();}
async function saveWriting(){if(!writingLoadedRid)return;clearTimeout(writingTimer);const saved=await(await api(`/reviews/${writingLoadedRid}/writing`,{method:'PUT',body:JSON.stringify(draftBody())})).json();writingData=saved;writingDirty=false;renderWritingMeta();}
function renderWritingMeta(){$('#draftSaveStatus').textContent=writingDirty?'Alterações não salvas':writingData.saved_at?'Salvo · '+stamp(writingData.saved_at):'Ainda sem versão salva';$('#draftSaveStatus').classList.toggle('writing-unsaved',writingDirty);$('#writingSources').innerHTML=`<p class="fine">${writingData.sources.length} artigo(s) aceito(s). ${writingData.sources.filter(s=>s.full_text_reviewed).length} com inclusão após texto completo.</p>`+writingData.sources.map(s=>`<div class="source-note"><strong>${esc(s.title)}</strong><br><a href="https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(s.pmid)}/" target="_blank" rel="noopener noreferrer">PMID ${esc(s.pmid)} ↗</a><p>${s.full_text_reviewed?'Texto completo avaliado':'Fonte preliminar · título/resumo'} · PDF ${s.pdf_status==='available'?'disponível':'pendente'}</p></div>`).join('');$('#writingComments').innerHTML=writingData.comments.filter(c=>!c.resolved).map(c=>`<div class="comment-note">${c.anchor?`<blockquote>${esc(c.anchor)}</blockquote>`:''}<p>${esc(c.text)}</p><button class="text-button" data-resolve-comment="${c.id}">Resolver</button></div>`).join('');$$('[data-resolve-comment]').forEach(b=>b.onclick=()=>action(async()=>{writingData=await(await api(`/reviews/${rid}/writing/comments/${b.dataset.resolveComment}/resolve`,{method:'POST'})).json();renderWritingMeta();},b));$('#writingVersions').innerHTML=writingData.revisions.slice().reverse().map(r=>`<p class="fine">${stamp(r.created_at)} · ${esc(r.id.slice(0,8))}</p>`).join('')||'<p class="fine">Nenhuma versão salva.</p>';}
function renderWritingActivity(){const j=snapshot?.jobs.filter(j=>j.kind==='writing').sort((a,b)=>b.created_at-a.created_at)[0];$('#writingActivity').innerHTML=j?`${['pending','running'].includes(j.status)?'<i class="spinner"></i>':''}<span>Assistência editorial · ${esc(j.status)}</span><button data-writing-history>Ver atividade e controles →</button>`:'';if($('[data-writing-history]'))$('[data-writing-history]').onclick=()=>{show('detail');renderDetail();setTab('history');if(hasActive(snapshot))startPolling();};}
function checkWritingResponse(){const j=snapshot?.jobs.filter(j=>j.kind==='writing'&&j.payload.result&&j.status==='done').sort((a,b)=>b.created_at-a.created_at)[0];if(!j||j.id===writingResponseId)return;writingResponseId=j.id;writingProposal=j;const r=j.payload.result;$('#aiReply').innerHTML=`<div class="ai-answer">${esc(r.content)}</div>${r.cautions?.length?`<div class="ai-cautions">${r.cautions.map(esc).join('<br>')}</div>`:''}`;$('#applyAi').hidden=j.payload.mode==='question';$('#aiPanel').hidden=false;}
async function askWriting(mode,instruction=''){if(!writingLoadedRid){message('Abra uma pesquisa na aba Prévia inicial para conversar sobre o trabalho.');return;}await saveWriting();await api(`/reviews/${rid}/writing/assist`,{method:'POST',body:JSON.stringify({mode,instruction})});$('#aiReply').textContent='Solicitação recebida. A atividade será atualizada automaticamente; você pode acompanhar ou cancelar pelo Histórico.';$('#applyAi').hidden=true;$('#aiPanel').hidden=false;await pollReview();startPolling();}
$('#writingReview').onchange=e=>action(()=>loadWriting(e.target.value));
for(const id of ['draftTitle','draftTheme','draftClient','draftInstructions','draftProduction','draftContent'])$('#'+id).oninput=()=>{writingDirty=true;$('#draftSaveStatus').textContent='Alterações não salvas · use Salvar versão';$('#draftSaveStatus').classList.add('writing-unsaved');};
$('#saveWriting').onclick=e=>action(saveWriting,e.currentTarget);
$('#generateWriting').onclick=e=>action(()=>askWriting('draft'),e.currentTarget);
$('#exportWriting').onclick=e=>action(async()=>{await saveWriting();await download(`/reviews/${rid}/writing/docx`,'previa-inicial.docx');},e.currentTarget);
$('#startWriting').onclick=()=>show('pre');
$('#writingResearch').onclick=()=>action(()=>loadReview(rid));
$('#draftFile').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('A ficha deve ter até 10 MB.');const d=await(await api('/documents/extract',{method:'POST',raw:true,headers:{'X-Filename':encodeURIComponent(f.name),'Content-Type':'application/octet-stream'},body:f})).json();$('#draftProduction').value=d.text;writingDirty=true;await saveWriting();message('Ficha incorporada ao trabalho.');});
$('#draftContent').onselect=()=>{const e=$('#draftContent');commentSelection=e.value.slice(e.selectionStart,e.selectionEnd).slice(0,2000);$('#commentAnchor').textContent=commentSelection?'Trecho: '+commentSelection:'Comentário geral';};
$('#addComment').onclick=e=>action(async()=>{const text=$('#commentText').value.trim();if(!text)throw Error('Escreva o comentário.');await saveWriting();writingData=await(await api(`/reviews/${rid}/writing/comments`,{method:'POST',body:JSON.stringify({text,anchor:commentSelection})})).json();$('#commentText').value='';renderWritingMeta();},e.currentTarget);
$('#aiToggle').onclick=()=>{if(view!=='pre'){show('pre');message('Selecione a pesquisa para conversar sobre a prévia.');}$('#aiPanel').hidden=!$('#aiPanel').hidden;};$('#closeAi').onclick=()=>$('#aiPanel').hidden=true;
$('#askAi').onclick=e=>action(async()=>{const instruction=$('#aiInstruction').value.trim();if(!instruction)throw Error('Escreva sua dúvida ou ajuste.');await askWriting($('#aiMode').value,instruction+(commentSelection?'\nTrecho selecionado: '+commentSelection:''));},e.currentTarget);
$('#applyAi').onclick=e=>action(async()=>{if(!writingProposal)return;if(writingDirty)throw Error('Salve suas alterações antes de aplicar a proposta.');const base=writingProposal.payload.context.revision;if(base!==writingData.revision)throw Error('A proposta foi gerada sobre uma versão anterior. Solicite uma nova correção para preservar suas alterações.');$('#draftContent').value=writingProposal.payload.result.content;writingDirty=true;await saveWriting();$('#applyAi').hidden=true;message('Proposta aplicada e nova versão salva.');},e.currentTarget);
window.addEventListener('beforeunload',e=>{if(writingDirty){e.preventDefault();e.returnValue='';}});
fetch('/health/ready').then(r=>{$('#systemStatus').textContent=r.ok?'● Sistema online':'● Sistema em ajustes';}).catch(()=>{$('#systemStatus').textContent='● Sistema indisponível';});

document.addEventListener('change',e=>{if(!e.target.matches('[data-upload-pdf]'))return;const f=e.target.files[0];if(!f)return;action(async()=>{if(f.size>20*1024*1024)throw Error('O PDF deve ter até 20 MB.');if(!confirm('Confirma que este PDF corresponde ao artigo selecionado e foi obtido com acesso autorizado?'))return;await api(`/reviews/${rid}/articles/${e.target.dataset.uploadPdf}/pdf`,{method:'POST',raw:true,headers:{'Content-Type':'application/pdf'},body:f});await pollReview();message('PDF anexado. Agora você pode avaliar o texto completo.');});});
